            StandardEvent("t_con_1", "Pistolet Automatique à Fil Détente", "Votre pied accroche un fil d'acier invisible relié à un pistolet automatique fixé dans le mur !", EventTag.TRAP, UniverseType.CONTEMPORARY, "Couper le fil de détente avec minutie", Skill.LOCK_TRAP, "Effectuer un plongeon au sol pour éviter le coup de feu", Skill.EXTREME_JUMP, "Casser le canon du pistolet dissimulé", Skill.BREAK),
            StandardEvent("t_con_2", "Câble Électrique Dénudé Sous Tension", "Un câble haute tension sectionné pend du plafond et étincelle au-dessus d'une flaque d'eau !", EventTag.TRAP, UniverseType.CONTEMPORARY, "Sauter par-dessus la flaque d'eau électrifiée", Skill.EXTREME_JUMP, "Couper l'alimentation du disjoncteur général", Skill.LOCK_TRAP, "Escalader les conduits au mur pour contourner l'eau", Skill.CLIMB),
            StandardEvent("t_con_3", "Colis Piégé à l'Explosif C4", "Une mallette abandonnée déclenche un compte à rebours numérique de 10 secondes dès qu'elle est déplacée !", EventTag.TRAP, UniverseType.CONTEMPORARY, "Couper le bon câble du détacheur d'explosif", Skill.LOCK_TRAP, "Balancer le colis piégé hors de la fenêtre à bout de bras", Skill.LIFT_PUSH, "Analyse logique du circuit imprimé pour bloquer le chrono", Skill.MAGIC),
            StandardEvent("t_con_4", "Trappe d'Égout Déverrouillée", "La plaque de fonte sous vos pieds bascule soudainement vers un conduit d'eaux usées vertigineux !", EventTag.TRAP, UniverseType.CONTEMPORARY, "Rattraper le rebord en béton d'un réflexe athlétique", Skill.CLIMB, "Sauter sur le trottoir solide d'un bond désespéré", Skill.EXTREME_JUMP, "Remonter en poussant sur vos bras le long du tuyau", Skill.LIFT_PUSH),
            StandardEvent("t_con_5", "Gaz Lacrymogène de Banque", "Les détecteurs de présence du sous-sol s'allument et expulsent un nuage toxique de gaz lacrymogène !", EventTag.TRAP, UniverseType.CONTEMPORARY, "Bloquer les buses d'expulsion de gaz", Skill.LOCK_TRAP, "Enfoncer la porte de sortie bloquée", Skill.BREAK, "Escalader la grille de secours pour atteindre la lucarne", Skill.CLIMB),
            StandardEvent("t_con_6", "Herse Épineuse de Parking", "Des piques d'acier rétractables pour pneus jaillissent du sol du parking souterrain sous votre passage !", EventTag.TRAP, UniverseType.CONTEMPORARY, "Sauter par-dessus le hérisson d'acier", Skill.EXTREME_JUMP, "Désactiver la borne de contrôle hydraulique", Skill.LOCK_TRAP, "Casser les piques d'acier avec un lourd tuyau", Skill.BREAK),
            StandardEvent("t_con_7", "Fenêtre Piégée au Détecteur Sécurisé", "Le cadre de la fenêtre du manoir cache un capteur de pression relié à une sirène d'alarme et des projecteurs !", EventTag.TRAP, UniverseType.CONTEMPORARY, "Dériver le courant du capteur de l'alarme", Skill.LOCK_TRAP, "Passer par-dessus la verrière sans toucher le cadre", Skill.EXTREME_JUMP, "Négocier rapidement par talkie-walkie avec la sécurité", Skill.PERSUASION),
            StandardEvent("t_con_8", "Pression d'Huile Glissante au Sol", "Une flaque d'huile moteur glissante a été déversée au sommet de l'escalier métallique !", EventTag.TRAP, UniverseType.CONTEMPORARY, "Rattraper votre équilibre et sauter jusqu'au palier", Skill.EXTREME_JUMP, "Agripper la main courante en acier pour ne pas chuter", Skill.CLIMB, "Détruire la barrière en bas pour amortir la chute", Skill.BREAK),
            StandardEvent("t_con_9", "Barrette de Démolition sur Serrure", "La serrure de la planque contient une mini-charge thermite prête à sauter à la moindre fausse clé !", EventTag.TRAP, UniverseType.CONTEMPORARY, "Désamorcer délicatement le système d'allumage thermite", Skill.LOCK_TRAP, "Forcer les gonds métalliques de la porte par l'extérieur", Skill.LIFT_PUSH, "Détecter les fils de charge par analyse thermique", Skill.MAGIC),
            StandardEvent("t_con_10", "Filet de Capture Suspendu", "Un lourd filet de corde d'acier dissimulé sous des feuilles mortes jaillit et tente de vous emprisonner !", EventTag.TRAP, UniverseType.CONTEMPORARY, "Esquiver le piège d'un bond latéral rapide", Skill.EXTREME_JUMP, "Trancher les mailles du filet à la lame", Skill.COMBAT, "Forcer le mécanisme de tension du câble", Skill.LIFT_PUSH),
            StandardEvent("evt_con_5", "Coffre-Fort Biométrique de Direction", "Un coffre-fort d'époque fermé par un code numérique complexe et un système de sécurité logique.", EventTag.RIDDLE, UniverseType.CONTEMPORARY, "Analyser les empreintes et trouver la combinaison manquante", Skill.MAGIC, "Crocheter la serrure mécanique de secours", Skill.LOCK_TRAP, "Utiliser la force pour détruire le mécanisme de fermeture", Skill.BREAK),

            // ==================== FUTURISTIC ====================
            // COMBAT (10)
            StandardEvent("c_fut_1", "Traqueur Cyber-Insectoïde", "Une monstrueuse araignée robotique à 8 pattes d'acier aiguisées comme des scalpels descend du plafond !", EventTag.COMBAT, UniverseType.FUTURISTIC, "Trancher ses pattes articulées d'un coup de sabre plasma", Skill.COMBAT, "Pirater ses puces d'orientation pour la verrouiller", Skill.LOCK_TRAP, "Surcharger sa batterie avec une décharge ionique", Skill.MAGIC),
            StandardEvent("c_fut_2", "Commando Cyborg de Néo-Tokyo", "Un soldat d'élite cyborg aux réflexes surhumains fond sur vous avec ses lames monomoléculaires !", EventTag.COMBAT, UniverseType.FUTURISTIC, "Parer l'assaut et contre-attaquer en duel au sabre", Skill.COMBAT, "Envoyer une impulsion EMP pour griller son système optique", Skill.MAGIC, "Sauter par-dessus la passerelle pour prendre de la hauteur", Skill.EXTREME_JUMP),
            StandardEvent("c_fut_3", "Clone de Combat Instable", "Un clone de laboratoire génétiquement modifié aux muscles hypertrophiés s'échappe de sa capsule et vous attaque !", EventTag.COMBAT, UniverseType.FUTURISTIC, "L'affronter directement au corps-à-corps", Skill.COMBAT, "Tirer une salve au blaster plasma dans son torse", Skill.SHOOT, "Détruire les conduits d'alimentation de sa capsule pour l'affaiblir", Skill.BREAK),
            StandardEvent("c_fut_4", "Dévoreur de Silicium Martien", "Une créature fouisseuse extraterrestre aux mâchoires de diamant émerge du sol de la colonie !", EventTag.COMBAT, UniverseType.FUTURISTIC, "Tirer une fusée thermique dans sa gueule béante", Skill.SHOOT, "Sauter sur son dos rocheux et viser son point faible", Skill.EXTREME_JUMP, "Surcharger le sol de la colonie d'énergie pour la faire fuir", Skill.MAGIC),
            StandardEvent("c_fut_5", "Exo-Squelette d'Assaut Autonome", "Une armure lourde de combat sans pilote contrôlée par une I.A. rebelle fait feu de toutes ses armes !", EventTag.COMBAT, UniverseType.FUTURISTIC, "Arroser le blindage d'un tir d'artillerie plasma", Skill.SHOOT, "Pirater le processeur central de l'I.A. en plein combat", Skill.LOCK_TRAP, "Détruire ses réacteurs dorsaux à coups de masse énergétique", Skill.BREAK),
            StandardEvent("c_fut_6", "Mutant des Bas-Fonds Cyberpunk", "Un habitant des égouts irradiés, défiguré et doté de bras tentaculaires, se jette sur vous !", EventTag.COMBAT, UniverseType.FUTURISTIC, "Trancher ses tentacules mutés au couteau vibratoire", Skill.COMBAT, "Négocier avec le mutant en invoquant la fraternité des bas-fonds", Skill.PERSUASION, "Utiliser un propulseur pour le repousser dans la fosse", Skill.LIFT_PUSH),
            StandardEvent("c_fut_7", "Bio-Prédateur Caméléon", "Une créature génétique invisible se déplace sur les parois en laissant une traînée de bave acide !", EventTag.COMBAT, UniverseType.FUTURISTIC, "Tirer aveuglément en balayant la zone au blaster", Skill.SHOOT, "Utiliser la magie du scanner thermique pour la révéler", Skill.MAGIC, "Escalader la structure pour la surprendre par le haut", Skill.CLIMB),
            StandardEvent("c_fut_8", "Mercenaire Cyber-Samouraï", "Un duelliste augmentant sa vitesse via un processeur neuronal dégaine son Katana énergétique !", EventTag.COMBAT, UniverseType.FUTURISTIC, "S'engager dans un duel à mort d'escrime ultra-rapide", Skill.COMBAT, "Intimider le samouraï en lui montrant votre maîtrise", Skill.PERSUASION, "Passer derrière lui grâce à une esquive propulsée", Skill.EXTREME_JUMP),
            StandardEvent("c_fut_9", "Meute de Cyber-Rats de Laboratoire", "Des dizaines de rats cybernétiques aux yeux rouges se ruent sur vous en une vague féroce !", EventTag.COMBAT, UniverseType.FUTURISTIC, "Brûler la vague avec une onde de feu plasma", Skill.MAGIC, "Broyer les premiers rangs d'une frappe sismique au sol", Skill.BREAK, "Grimper vivement sur une armoire de données élevée", Skill.CLIMB),
            StandardEvent("c_fut_10", "Titan Mécanique de la Décharge", "Un assemblage colossal d'épaves de vaisseaux s'anime sous l'impulsion d'un noyau magnétique !", EventTag.COMBAT, UniverseType.FUTURISTIC, "Détruire l'émetteur magnétique au cœur de la structure", Skill.BREAK, "Pirater les relais d'aimantation pour disloquer le titan", Skill.LOCK_TRAP, "Soulever un câble haute tension pour électrocuter la masse", Skill.LIFT_PUSH),

